import sys
import EfiPy2 as EfiPy
from EfiPy2.MdePkg.IndustryStandard import Acpi, EFIPY_INDUSTRY_STRUCTURE

#
# BGRT Status Bit Field Definition (ACPI 6.5 Table 5.48)
# EDK2 MdePkg defines Status as a raw UINT8 without bit field expansion.
# We define a Union here to allow DumpStruct to display Displayed and OrientationOffset.
#
class BGRT_STATUS_BITS (EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Displayed",         EfiPy.UINT8, 1),
        ("OrientationOffset", EfiPy.UINT8, 2),
        ("Reserved",          EfiPy.UINT8, 5),
    ]

class BGRT_STATUS (EfiPy.Union):
    _fields_ = [
        ("Uint8", EfiPy.UINT8),
        ("Bits",  BGRT_STATUS_BITS),
    ]

#
# Boot Graphics Resource Table Structure with decomposed Status
#
class EFI_ACPI_6_5_BOOT_GRAPHICS_RESOURCE_TABLE (EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
        ("Header",       Acpi.EFI_ACPI_DESCRIPTION_HEADER),
        ("Version",      EfiPy.UINT16),
        ("Status",       BGRT_STATUS),
        ("ImageType",    EfiPy.UINT8),
        ("ImageAddress", EfiPy.UINT64),
        ("ImageOffsetX", EfiPy.UINT32),
        ("ImageOffsetY", EfiPy.UINT32),
    ]

def AcpiBgrtParser (BgrtRaw):

    if not BgrtRaw or len (BgrtRaw) < 56:
        return None, None

    Header = Acpi.EFI_ACPI_DESCRIPTION_HEADER.from_buffer_copy (BgrtRaw)
    if Header.Length != 56 or len (BgrtRaw) < Header.Length:
        return None, None

    BgrtType = EFI_ACPI_6_5_BOOT_GRAPHICS_RESOURCE_TABLE
    BgrtObj  = BgrtType.from_buffer_copy (BgrtRaw)

    return BgrtObj, BgrtType

if __name__ == '__main__':

    import os
    from EfiPy2.Lib.StructDump import DumpStruct
    from EfiPy2.Lib.HexDump import HexDump

    if len (sys.argv) < 2:
        print (f"Usage: {sys.argv[0]} <BgrtBinaryFile>")
        sys.exit (1)

    BgrtFileName = sys.argv[1]
    if not os.path.isfile (BgrtFileName):
        print (f"Open {BgrtFileName} error.")
        sys.exit (-1)

    with open (BgrtFileName, 'rb') as BgrtFileHandle:
        BgrtRaw = bytearray (BgrtFileHandle.read ())

    BgrtObj, BgrtType = AcpiBgrtParser (BgrtRaw)
    if BgrtObj is None:
        print (f"Parse {BgrtFileName} error.")
        sys.exit (-1)

    DumpStruct (2, BgrtObj, BgrtType)
    print ('\n==== ACPI BGRT RAW data ======')
    HexDump (BgrtRaw)
